<?php use ImWiki\Security\Csrf;use ImWiki\Security\Html;use ImWiki\Support\Url;$title='Moje szkice';?>
<div class="page-head"><div><p class="eyebrow">Treść</p><h1>Moje szkice</h1><p class="muted">Autosave nie publikuje strony i nie tworzy wersji.</p></div></div>
<section class="card section-card"><?php if(!$drafts):?><div class="empty-state"><p class="muted">Nie masz zapisanych szkiców.</p></div><?php endif;?><?php foreach($drafts as $draft):?><div class="list-row"><span><strong><?=Html::e($draft['title']?:$draft['page_title'])?></strong><small><?=Html::e($draft['space_name'])?> · <?=Html::e($draft['updated_at'])?></small></span><div class="actions"><a class="button secondary" href="<?=Html::e(Url::to('/pages/'.$draft['page_id'].'/edit?draft='.$draft['id']))?>">Kontynuuj</a><form method="post" action="<?=Html::e(Url::to('/drafts/'.$draft['id'].'/delete'))?>" onsubmit="return confirm('Usunąć ten szkic?')"><?=Csrf::field()?><button class="button secondary">Usuń</button></form></div></div><?php endforeach;?></section>
